INSERT INTO `about_doctors` (`id`, `name`, `slug`, `degree`, `designation`, `about`, `image`, `youtube`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Prof. Dr. AKM Fazlul Haque', 'doc_1', 'MBBS, FCPS, FICS', 'Fellow, Colorectal Surgery (Singapore)\nInternational Scholar, Colorectal Surgery (USA)\n\nFounder Chairman (RETD.), Chief Consultant (Chairman)\nColorectal Surgery Department\nDr. Fazlul Haque Colorectal Hospital Ltd.\n\nDepartment of Colorectal Surgery\nBangladesh Medical University, Dhaka', 'Professor Dr. AKM Fazlul Haque was the founder Chairman and Professor of the Department of\n                        Colorectal Surgery in Bangladesh Medical University, Dhaka, the only Medical University in\n                        Bangladesh. He obtained MBBS Degree from Dhaka Medical College in 1982 and was awarded\n                        Fellowship (FCPS, Surgery) from Bangladesh College of Physicians and Surgeons in January\n                        1989. He worked in Government health service in Bangladesh starting from April 1982 until\n                        2009. He served as a registrar in the department of surgery for one year in Singapore General\n                        Hospital in 1995 – 1996. He is the best and most experienced doctor of Colorectal Surgery\n                        specially in Bangladesh. He is also the Pioneer Colorectal Surgeon in South Asian Subcontinent\n                        (India, Bangladesh, Nepal, and Pakistan). Chief Consultant (Chairman), Colorectal Surgery\n                        Department. Dr. Fazlul Haque Colorectal Hospital Ltd.', 'uploads/images/welcome_page/doctors/image_1.jpg', NULL, 1, NULL, NULL),
(2, 'Dr. Asif Almas Haque', 'doc_2', 'MBBS (SSMC), FCPS (Surgery), FCPS (Colorectal Surgery), FRCS (England), FRCS (Glasgow), FRCS (Edinburgh), FACS (USA), FASCRS (USA)', 'Consultant, Colorectal, Laparoscopic and Laser Surgeon\nMember, American Society of Colon and Rectal Surgeons', 'Dr. Asif Almas Haque is one of the leading colorectal surgeons in Bangladesh.\n\nHe specializes in colorectal surgery, laparoscopic surgery, and laser surgery. He has successfully performed numerous complex colorectal procedures with excellent patient outcomes.\n\nHe is known for his compassionate approach and commitment to providing high quality patient care.', 'uploads/images/welcome_page/doctors/image_2.jpg', 'https://www.youtube.com/embed/txHKFJtOqYE', 1, NULL, NULL),
(3, 'Dr. Fatema Sharmin (Anny)', 'doc_3', 'MBBS, DA, FCPS (Final Part)', 'Consultant (Anesthesiology)\nDr. Fazlul Haque Colorectal Hospital Limited\n\nAssistant Professor (Anesthesiology)\nBangladesh Medical College Hospital, Dhanmondi', 'Dr. Fatema Sharmin (Anny) is an experienced anesthesiology consultant with strong expertise in anesthesia management during complex surgical procedures.\n\nShe is known for her patient focused care and dedication to maintaining the highest safety standards in operation theaters.', 'uploads/images/welcome_page/doctors/image_3.jpg', NULL, 1, NULL, NULL),
(4, 'Dr. Sakib Sarwat Haque', 'doc_4', 'MBBS, FCPS (Surgery), MRCS (Edinburgh)', 'Consultant Surgeon\nDr. Fazlul Haque Colorectal Hospital Ltd.', 'Dr. Sakib Sarwat Haque is a consultant surgeon trained in general and colorectal surgery.\n\nHe focuses on delivering safe, modern, and patient-centered surgical care and actively participates in both elective and emergency surgical treatments.', 'uploads/images/welcome_page/doctors/image_4.jpg', NULL, 1, NULL, NULL),
(5, 'Dr. Asma Husain Noora', 'doc_5', 'MBBS, FCPS (Surgery), MRCS (Edinburgh)', 'Consultant Surgeon\nDr. Fazlul Haque Colorectal Hospital Ltd', 'Dr. Asma Husain Noora is a consultant surgeon with strong clinical and academic training.\n\nShe is experienced in modern surgical techniques and is dedicated to ensuring patient safety and excellent surgical outcomes.', 'uploads/images/welcome_page/doctors/image_5.jpg', NULL, 1, NULL, NULL);
